import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from "./UserProfileCard";

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // Clears other datasets so only one appears at a time
  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  // common fetch utility
  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");

    clearAll(); // Ensures only 1 dataset visible at a time

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error(errMsg);
      const data = await res.json();

      setter(data[field] || []);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  // Most Active NGO Loader
  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");

    clearAll(); // ensure only one dataset visible

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to load most active NGO");

      const data = await res.json();
      setMostActive(data.top || null);
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  // Delete NGO
  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to delete NGO");
      setMsg("NGO removed successfully");

      setNgos((prev) => prev.filter((n) => n.id !== id));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  return (
    <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
      {/* LEFT PANEL */}
      <div style={{ width: 320, flexShrink: 0 }}>
        <UserProfileCard token={token} setMsg={setMsg} />

        <div style={{ marginTop: 12 }}>
          <AchievementsPanel
            token={token}
            me={{ points: reports?.adminPoints || 0 }}
            role="user"
            setMsg={setMsg}
          />
        </div>
      </div>

      {/* MIDDLE PANEL */}
      <div style={{ flex: 1 }}>
        {/* PROFILE ICON + HEADING */}
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <img
            src="https://cdn-icons-png.flaticon.com/512/9131/9131529.png"
            alt="profile"
            style={{ width: 40, height: 40 }}
          />
          <h2 style={{ margin: 0 }}>Admin Dashboard</h2>
        </div>

        <h3 style={{ marginTop: 10 }}>Admin Reports</h3>

        <div className="cards">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations
                ? reports.donations.reduce(
                    (sum, d) => sum + parseFloat(d.amount || 0),
                    0
                  )
                : "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>

        {/* ACTION BUTTONS - Equal Spacing */}
        <div style={{ marginTop: 15, display: "flex", gap: 12 }}>
          <button
            onClick={() =>
              loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
            }
            style={{ padding: "10px 14px" }}
          >
            View NGOs
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/registered-events",
                setEvents,
                "events",
                "Failed to load events"
              )
            }
            style={{ padding: "10px 14px" }}
          >
            View Events
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/event-stats",
                setEventStats,
                "events",
                "Failed to load stats"
              )
            }
            style={{ padding: "10px 14px" }}
          >
            View Stats
          </button>
        </div>

        {/* ONLY ONE DATA SECTION SHOWS AT A TIME */}
        {events && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered Events</h4>
            {events.length ? (
              events.map((e) => (
                <div
                  key={e.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                  }}
                >
                  <strong>{e.title}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{e.date}</div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {eventStats && (
          <div style={{ marginTop: 20 }}>
            <h4>Event Statistics</h4>
            {eventStats.length ? (
              eventStats.map((ev) => (
                <div
                  key={ev.id}
                  style={{
                    display: "flex",
                    gap: 12,
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                  }}
                >
                  <img
                    src={ev.image_url || "https://via.placeholder.com/120x80"}
                    alt="ev"
                    style={{
                      width: 100,
                      height: 64,
                      objectFit: "cover",
                      borderRadius: 6,
                    }}
                  />
                  <div>
                    <div style={{ fontWeight: 600 }}>{ev.title}</div>
                    <div style={{ fontSize: 13, color: "#666" }}>
                      Volunteers: {ev.volunteers_count} — Donations: ₹
                      {ev.donations_sum}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <p>No event statistics loaded.</p>
            )}
          </div>
        )}

        {ngos && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {ngos.length ? (
              ngos.map((n) => (
                <div
                  key={n.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <strong>{n.name}</strong>
                    <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                  </div>

                  <button
                    style={{
                      padding: "6px 12px",
                      background: "red",
                      color: "white",
                      border: "none",
                      borderRadius: 6,
                      cursor: "pointer",
                    }}
                    onClick={() => deleteNgo(n.id)}
                  >
                    Remove
                  </button>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: 280, flexShrink: 0, position: "sticky", top: 16 }}>
        <div
          style={{
            background: "#fff",
            padding: 12,
            borderRadius: 10,
            boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
          }}
        >
          <h4>Quick Actions</h4>

          <button
            onClick={() =>
              loadData(
                "/api/actions/top-volunteers",
                setEventStats,
                "top",
                "Failed to load top volunteers"
              )
            }
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Volunteer
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/top-donors",
                setEventStats,
                "top",
                "Failed to load top donors"
              )
            }
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Donor
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/badges",
                setEventStats,
                "badges",
                "Failed to load badges"
              )
            }
            style={{ width: "100%", padding: 10, borderRadius: 8 }}
          >
            View Badges
          </button>
        </div>

        {/* ⭐ MOST ACTIVE NGO BELOW QUICK LINKS ⭐ */}
        <div
          style={{
            background: "#fff",
            marginTop: 20,
            padding: 12,
            borderRadius: 10,
            boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
          }}
        >
          <h4>Most Active NGO</h4>

          <button
            onClick={loadMostActive}
            style={{ marginTop: 8, padding: 8, width: "100%", borderRadius: 6 }}
          >
            Load Most Active NGO
          </button>

          {mostActive && (
            <div style={{ marginTop: 12 }}>
              <strong>{mostActive.name}</strong>
              <div style={{ fontSize: 13, color: "#666" }}>
                Activity Score: {mostActive.activity_score}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
